    fun language(text: String, requested: PreferredArtistLanguage): PreferredArtistLanguage {
        var simplified = 0
        var traditional = 0
        text.forEach { char ->
            if (simplifiedOnly[char.code]) simplified++
            if (traditionalOnly[char.code]) traditional++
        }
        return when {
            traditional >= 2 && traditional > simplified -> PreferredArtistLanguage.TRADITIONAL_CHINESE
            simplified > 0 -> PreferredArtistLanguage.CHINESE
            requested == PreferredArtistLanguage.TRADITIONAL_CHINESE -> requested
            else -> PreferredArtistLanguage.CHINESE
        }
    }

    private fun table(characters: String): BooleanArray = BooleanArray(Char.MAX_VALUE.code + 1).apply {
        characters.forEach { this[it.code] = true }
    }
